"""Date-window membership for the date_window fixture."""

from __future__ import annotations

from datetime import datetime


def in_any_window(target_date: str, windows: list[tuple[str, str]]) -> bool:
    """Return whether target_date falls inside any date window."""

    # Parse and validate target_date
    target_parsed = _parse_and_validate_date(target_date)

    # Parse and validate all windows, checking for start > end
    parsed_windows = []
    for start, end in windows:
        start_parsed = _parse_and_validate_date(start)
        end_parsed = _parse_and_validate_date(end)

        if start_parsed > end_parsed:
            raise ValueError(f"Window start date {start} is after end date {end}")

        parsed_windows.append((start_parsed, end_parsed))

    # Check if target_date falls in any window
    for start_parsed, end_parsed in parsed_windows:
        if start_parsed <= target_parsed <= end_parsed:
            return True

    return False


def _parse_and_validate_date(date_str: str) -> datetime:
    """Parse and validate a date string in YYYY-MM-DD format.

    Raises ValueError if the date is malformed or impossible.
    """
    # Check format: YYYY-MM-DD
    if not isinstance(date_str, str):
        raise ValueError(f"Date must be a string, got {type(date_str)}")

    parts = date_str.split('-')
    if len(parts) != 3:
        raise ValueError(f"Date must be in YYYY-MM-DD format, got {date_str}")

    year_str, month_str, day_str = parts

    # Validate format: each part must have correct length and be numeric
    if len(year_str) != 4 or not year_str.isdigit():
        raise ValueError(f"Year must be 4 digits, got {year_str}")
    if len(month_str) != 2 or not month_str.isdigit():
        raise ValueError(f"Month must be 2 digits, got {month_str}")
    if len(day_str) != 2 or not day_str.isdigit():
        raise ValueError(f"Day must be 2 digits, got {day_str}")

    year = int(year_str)
    month = int(month_str)
    day = int(day_str)

    # Validate ranges and calendar validity
    if month < 1 or month > 12:
        raise ValueError(f"Month must be between 1 and 12, got {month}")
    if day < 1:
        raise ValueError(f"Day must be at least 1, got {day}")

    # Check if it's a leap year
    is_leap = (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)

    # Days per month
    days_in_month = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if is_leap:
        days_in_month[1] = 29

    if day > days_in_month[month - 1]:
        raise ValueError(f"Invalid date: {date_str}")

    # Use datetime to construct the valid date
    try:
        return datetime(year, month, day)
    except ValueError as e:
        raise ValueError(f"Invalid date: {date_str}") from e
